import pytest

import falcon
import falcon.asgi
import falcon.testing as testing


class Reports(list):
    def __call__(self, req, ex, params, handled):
        self.append((req, ex, params, handled))

    @property
    def summary(self):
        return [(type(ex), handled) for _, ex, _, handled in self]


class CustomError(Exception):
    pass


def _resource(asgi, body):
    if asgi:

        class Resource:
            async def on_get(self, req, resp, **params):
                body(req, resp, **params)

    else:

        class Resource:
            def on_get(self, req, resp, **params):
                body(req, resp, **params)

    return Resource()


def _handler(asgi, body):
    if asgi:

        async def handler(req, resp, ex, params):
            body(req, resp, ex, params)

    else:

        def handler(req, resp, ex, params):
            body(req, resp, ex, params)

    return handler


def _raiser(ex_or_type):
    def body(*args, **kwargs):
        raise ex_or_type

    return body


@pytest.fixture
def reports():
    return Reports()


@pytest.fixture
def app(asgi, util, reports):
    app = util.create_app(asgi)
    app.set_error_reporter(reports)
    return app


@pytest.fixture
def client(app):
    return testing.TestClient(app)


def test_no_reporter(asgi, util):
    app = util.create_app(asgi)
    app.add_route('/', _resource(asgi, _raiser(falcon.HTTPGone)))
    assert testing.simulate_get(app, '/').status_code == 410


def test_route_not_found(client, reports):
    assert client.simulate_get('/nope').status_code == 404
    assert reports.summary == [(falcon.HTTPRouteNotFound, True)]


def test_replace_reporter(asgi, app, client, reports):
    other = Reports()
    app.set_error_reporter(other)
    client.simulate_get('/nope')
    assert not reports
    assert len(other) == 1

    app.set_error_reporter(None)
    client.simulate_get('/nope')
    assert len(other) == 1


def test_responder_error_params(asgi, app, client, reports):
    app.add_route('/items/{item_id:int}', _resource(asgi, _raiser(CustomError)))
    app.add_error_handler(
        CustomError,
        _handler(asgi, lambda req, resp, ex, params: setattr(resp, 'status', 418)),
    )

    assert client.simulate_get('/items/7').status_code == 418
    ((req, ex, params, handled),) = reports
    assert req.path == '/items/7'
    assert isinstance(ex, CustomError)
    assert params == {'item_id': 7}
    assert handled is True


def test_reported_before_handler(asgi, app, client, reports):
    seen = []
    app.add_route('/', _resource(asgi, _raiser(CustomError)))
    app.add_error_handler(
        CustomError,
        _handler(asgi, lambda req, resp, ex, params: seen.append(len(reports))),
    )

    client.simulate_get('/')
    assert seen == [1]


def test_default_python_handler(app, asgi, client, reports):
    app.add_route('/', _resource(asgi, _raiser(CustomError)))
    assert client.simulate_get('/').status_code == 500
    assert reports.summary == [(CustomError, True)]


def test_unhandled(asgi, app, client, reports):
    app.add_route('/', _resource(asgi, _raiser(CustomError)))
    app._error_handlers.pop(Exception)

    with pytest.raises(CustomError):
        client.simulate_get('/')
    assert reports.summary == [(CustomError, False)]


def test_middleware_error(asgi, util, reports):
    if asgi:

        class Middleware:
            async def process_response(self, req, resp, resource, req_succeeded):
                raise falcon.HTTPConflict()

    else:

        class Middleware:
            def process_response(self, req, resp, resource, req_succeeded):
                raise falcon.HTTPConflict()

    app = util.create_app(asgi, middleware=[Middleware()])
    app.set_error_reporter(reports)
    app.add_route('/', _resource(asgi, lambda req, resp: None))

    assert testing.simulate_get(app, '/').status_code == 409
    assert reports.summary == [(falcon.HTTPConflict, True)]


def test_render_body_error(asgi, app, client, reports):
    def body(req, resp):
        resp.media = {'key': object()}

    app.add_route('/', _resource(asgi, body))
    assert client.simulate_get('/').status_code == 500
    assert reports.summary == [(TypeError, True)]


def test_handler_reraises_same(asgi, app, client, reports):
    def reraise(req, resp, ex, params):
        raise ex

    app.add_route('/gone', _resource(asgi, _raiser(falcon.HTTPGone)))
    app.add_route('/custom', _resource(asgi, _raiser(CustomError)))
    app.add_error_handler((falcon.HTTPGone, CustomError), _handler(asgi, reraise))

    assert client.simulate_get('/gone').status_code == 410
    assert reports.summary == [(falcon.HTTPGone, True)]

    del reports[:]
    with pytest.raises(CustomError):
        client.simulate_get('/custom')
    assert reports.summary == [(CustomError, True)]


@pytest.mark.parametrize(
    'raised,status',
    [(falcon.HTTPStatus(falcon.HTTP_202), 202), (falcon.HTTPGone(), 410)],
)
def test_handler_raises_http(asgi, app, client, reports, raised, status):
    def body(req, resp):
        1 / 0

    app.add_route('/', _resource(asgi, body))
    app.add_error_handler(ZeroDivisionError, _handler(asgi, _raiser(raised)))

    assert client.simulate_get('/').status_code == status
    assert reports.summary == [(ZeroDivisionError, True), (type(raised), True)]
    assert reports[1][1] is raised


def test_handler_raises_other(asgi, app, reports):
    app.add_route('/', _resource(asgi, _raiser(CustomError)))
    app.add_error_handler(CustomError, _handler(asgi, _raiser(ValueError('oops'))))

    if asgi:
        with pytest.raises(ValueError):
            testing.simulate_get(app, '/')
    else:
        srmock = testing.StartResponseMock()
        env = testing.create_environ('/')
        with pytest.raises(ValueError):
            app(env, srmock)
        assert env['wsgi.errors'].getvalue() == ''

    assert reports.summary == [(CustomError, True), (ValueError, False)]


def test_serializer_raises(asgi, app, reports):
    app.add_route('/', _resource(asgi, _raiser(falcon.HTTPGone)))
    app.set_error_serializer(_raiser(CustomError))

    if asgi:
        with pytest.raises(CustomError):
            testing.simulate_get(app, '/')
    else:
        env = testing.create_environ('/')
        with pytest.raises(CustomError):
            app(env, testing.StartResponseMock())
        assert env['wsgi.errors'].getvalue() == ''

    assert reports.summary == [(falcon.HTTPGone, True), (CustomError, False)]


def test_serializer_raises_after_handler_raised(asgi, app, client, reports):
    app.add_route('/', _resource(asgi, _raiser(CustomError)))
    app.add_error_handler(CustomError, _handler(asgi, _raiser(falcon.HTTPGone)))
    app.set_error_serializer(_raiser(KeyError))

    with pytest.raises(KeyError):
        client.simulate_get('/')
    assert reports.summary == [
        (CustomError, True),
        (falcon.HTTPGone, True),
        (KeyError, False),
    ]


def test_invalid_status(asgi, app, client, reports):
    def body(req, resp):
        resp.status = 'banana'

    app.add_route('/', _resource(asgi, body))

    with pytest.raises(ValueError):
        client.simulate_get('/')
    assert reports.summary == [(ValueError, False)]


def test_invalid_status_no_reporter(asgi, app, client, reports):
    def body(req, resp):
        resp.status = 'banana'

    app.set_error_reporter(None)
    app.add_route('/', _resource(asgi, body))

    with pytest.raises(ValueError):
        client.simulate_get('/')
    assert not reports


@pytest.mark.parametrize('with_reporter', [True, False])
@pytest.mark.parametrize('kind', ['data', 'empty', 'head', 'stream', 'sse'])
def test_asgi_header_cannot_be_encoded(util, reports, kind, with_reporter):
    async def stream():
        yield b'x'

    async def emitter():
        yield falcon.asgi.SSEvent(text='x')

    class Resource:
        async def on_get(self, req, resp):
            resp.set_header('X-Thing', 'ሴ')
            if kind == 'data':
                resp.text = 'hello'
            elif kind == 'stream':
                resp.stream = stream()
            elif kind == 'sse':
                resp.sse = emitter()

        on_head = on_get

    app = util.create_app(asgi=True)
    if with_reporter:
        app.set_error_reporter(reports)
    app.add_route('/', Resource())

    with pytest.raises(UnicodeEncodeError):
        testing.simulate_request(app, 'HEAD' if kind == 'head' else 'GET', '/')
    assert reports.summary == ([(UnicodeEncodeError, False)] if with_reporter else [])


def test_wsgi_start_response_fails(reports):
    def body(req, resp):
        resp.text = 'hello'

    def start_response(status, headers):
        raise CustomError

    for reporter in (reports, None):
        app = falcon.App()
        app.set_error_reporter(reporter)
        app.add_route('/', _resource(False, body))

        with pytest.raises(CustomError):
            app(testing.create_environ('/'), start_response)

    assert reports.summary == [(CustomError, False)]


@pytest.mark.parametrize('handler_raises', [None, falcon.HTTPStatus(403), KeyError()])
async def test_websocket(util, reports, handler_raises):
    class Resource:
        async def on_websocket(self, req, ws, **params):
            await ws.accept()
            raise CustomError

    async def handler(req, resp, ex, params, ws=None):
        raise handler_raises

    app = util.create_app(asgi=True)
    app.set_error_reporter(reports)
    app.add_route('/{name}', Resource())
    if handler_raises is not None:
        app.add_error_handler(CustomError, handler)

    async with testing.ASGIConductor(app) as conductor:
        if isinstance(handler_raises, KeyError):
            with pytest.raises(KeyError):
                async with conductor.simulate_ws('/bob'):
                    pass  # pragma: no cover
        else:
            with pytest.raises(falcon.WebSocketDisconnected):
                async with conductor.simulate_ws('/bob') as ws:
                    await ws.receive_text()

    assert reports[0][2] == {'name': 'bob'}
    expected = [(CustomError, True)]
    if handler_raises is not None:
        expected.append((type(handler_raises), not isinstance(handler_raises, KeyError)))
    assert reports.summary == expected
